insert into opd.emr_section (section_key, name, kind, description, always_shown, position) values
  ('vitals', 'Vitals', 'COMMON', 'BP, pulse, temperature, SpO2, weight, height and auto BMI. Usually filled by the assistant before the doctor sees the patient.', false, 1),
  ('complaints', 'Chief complaints', 'COMMON', 'What the patient came in for, with duration and severity.', false, 2),
  ('hpi', 'History of present illness', 'COMMON', 'A short story of the current illness. Supports voice dictation and saved phrases.', false, 3),
  ('history', 'Past, family & personal history', 'COMMON', 'Known illnesses, surgeries, family history and habits. Carried forward between visits.', false, 4),
  ('allergy', 'Allergies', 'COMMON', 'Drug and food allergies. A drug allergy shows a warning when that drug is prescribed.', true, 5),
  ('exam', 'General & systemic examination', 'COMMON', 'General signs plus CVS, RS, P/A and CNS, with normal findings pre-filled.', false, 6),
  ('diagnosis', 'Diagnosis', 'COMMON', 'Provisional and final diagnosis, coded for reports and insurance.', false, 7),
  ('investigations', 'Investigations', 'COMMON', 'Order lab and radiology tests, and record results with reference ranges.', false, 8),
  ('rx', 'Prescription (Rx)', 'COMMON', 'Medicines with dose, frequency and duration. Generic name shown first, as the NMC requires.', false, 9),
  ('advice', 'Advice & diet', 'COMMON', 'Lifestyle advice and printable diet charts.', false, 10),
  ('procedures', 'Procedures', 'COMMON', 'Minor procedures done in the clinic. Each one adds its charge to the bill.', false, 11),
  ('followup', 'Follow-up', 'COMMON', 'Next visit date. Can book the appointment and send a reminder.', false, 12),
  ('referral', 'Referral', 'COMMON', 'Refer to another doctor or hospital, with an auto-generated letter.', false, 13),
  ('attachments', 'Attachments & images', 'COMMON', 'Old reports, photos and scans for this visit.', false, 14),
  ('abha', 'ABHA / ABDM link', 'COMPLIANCE', 'Link the visit to the patient’s ABHA ID so records can be shared through ABDM with their consent.', false, 15),
  ('consent', 'Consent forms', 'COMPLIANCE', 'Procedure-specific consent forms with patient or guardian signature.', false, 16),
  ('rxformat', 'Prescription print format', 'COMPLIANCE', 'Letterhead with doctor’s registration number and degree, and the print language.', false, 17),
  ('pcpndt', 'PCPNDT Form F', 'COMPLIANCE', 'Form F has to be filled for every obstetric ultrasound under the PCPNDT Act.', false, 18),
  ('chronic', 'Chronic disease tracker', 'SPECIALTY', 'Tracks BP, sugar and other readings across visits for long-term patients.', false, 19),
  ('adult_vax', 'Adult vaccination', 'SPECIALTY', 'Flu, pneumococcal, Td and other adult vaccines.', false, 20),
  ('dental_chart', 'Dental chart (odontogram)', 'SPECIALTY', 'Tap a tooth to mark its condition. Uses FDI numbering by default.', false, 21),
  ('intraoral', 'Intra-oral examination', 'SPECIALTY', 'Soft tissue, oral hygiene and occlusion.', false, 22),
  ('extraoral', 'Extra-oral examination', 'SPECIALTY', 'Face, TMJ and lymph nodes.', false, 23),
  ('perio', 'Periodontal charting', 'SPECIALTY', 'Pocket depth, bleeding and mobility for each tooth.', false, 24),
  ('tx_plan', 'Treatment plan & estimate', 'SPECIALTY', 'Planned procedures by tooth and phase, with a cost estimate the patient signs.', false, 25),
  ('dental_done', 'Procedures done', 'SPECIALTY', 'What was done today, on which tooth, and which sitting.', false, 26),
  ('dental_lab', 'Lab work', 'SPECIALTY', 'Crowns, bridges, dentures and aligners sent to the lab.', false, 27),
  ('menstrual', 'Menstrual history', 'SPECIALTY', 'LMP, cycle pattern and flow. LMP is used to work out EDD.', false, 28),
  ('obstetric', 'Obstetric history', 'SPECIALTY', 'Gravida, para, living and abortions, plus details of earlier pregnancies.', false, 29),
  ('anc', 'ANC visit card', 'SPECIALTY', 'Antenatal visit record with gestational age, EDD and risk flags.', false, 30),
  ('gyn_exam', 'P/A, P/S & P/V examination', 'SPECIALTY', 'Abdominal, speculum and vaginal examination findings.', false, 31),
  ('usg', 'USG findings', 'SPECIALTY', 'Dating, NT, anomaly and growth scans.', false, 32),
  ('infertility', 'Infertility workup', 'SPECIALTY', 'Hormone tests, follicle tracking and partner semen analysis.', false, 33),
  ('contraception', 'Contraception', 'SPECIALTY', 'Method chosen, start date and follow-up.', false, 34),
  ('growth', 'Growth chart', 'SPECIALTY', 'Weight, height and head size plotted on WHO and IAP charts.', false, 35),
  ('immunization', 'Immunization (IAP schedule)', 'SPECIALTY', 'Due and overdue vaccines from date of birth, with batch numbers and reminders.', false, 36),
  ('milestones', 'Developmental milestones', 'SPECIALTY', 'Motor, language and social milestones, with age-based red flags.', false, 37),
  ('birth', 'Birth history', 'SPECIALTY', 'Gestation at birth, birth weight, mode of delivery and NICU stay.', false, 38),
  ('feeding', 'Feeding history', 'SPECIALTY', 'Breastfeeding, top feeds and weaning.', false, 39),
  ('wtdose', 'Weight-based dosing', 'SPECIALTY', 'Works out the dose in mg/kg from the latest weight and warns above the maximum.', false, 40),
  ('pain', 'Pain assessment', 'SPECIALTY', 'Pain score, where it hurts and what makes it better or worse.', false, 41),
  ('posture', 'Posture & gait', 'SPECIALTY', 'Posture observation and gait pattern.', false, 42),
  ('rom', 'Range of motion (goniometry)', 'SPECIALTY', 'Active and passive range for each joint and side, with the normal range shown.', false, 43),
  ('mmt', 'Manual muscle testing', 'SPECIALTY', 'Muscle strength by group and side.', false, 44),
  ('special_tests', 'Special tests', 'SPECIALTY', 'Orthopaedic and neuro tests with result.', false, 45),
  ('func_scales', 'Outcome scales', 'SPECIALTY', 'Standard function scores to show progress.', false, 46),
  ('goals', 'Treatment goals', 'SPECIALTY', 'Short-term and long-term goals.', false, 47),
  ('modalities', 'Treatment modalities', 'SPECIALTY', 'Electrotherapy and other modalities given in the session.', false, 48),
  ('hep', 'Home exercise program', 'SPECIALTY', 'Exercises with pictures, sets and reps, shared with the patient.', false, 49),
  ('sessions', 'Session & package tracker', 'SPECIALTY', 'Tracks sessions used out of a package and the trend in pain and movement.', false, 50),
  ('ortho_local', 'Local examination', 'SPECIALTY', 'Look, feel and move for the affected part.', false, 51),
  ('fracture', 'Fracture & imaging', 'SPECIALTY', 'Fracture type, side and X-ray findings.', false, 52),
  ('cast', 'Cast / splint', 'SPECIALTY', 'Type, date applied and date due for removal.', false, 53),
  ('va', 'Visual acuity', 'SPECIALTY', 'Distance and near vision for each eye.', false, 54),
  ('refraction', 'Refraction & glasses Rx', 'SPECIALTY', 'Sphere, cylinder and axis for each eye, printed as a glasses prescription.', false, 55),
  ('iop', 'IOP', 'SPECIALTY', 'Eye pressure for each eye and method used.', false, 56),
  ('slitlamp', 'Slit lamp examination', 'SPECIALTY', 'Lids, conjunctiva, cornea, AC, iris and lens.', false, 57),
  ('fundus', 'Fundus', 'SPECIALTY', 'Disc, macula and vessels.', false, 58),
  ('otoscopy', 'Ear examination', 'SPECIALTY', 'Otoscopy findings for each ear.', false, 59),
  ('nose_throat', 'Nose & throat', 'SPECIALTY', 'Anterior rhinoscopy, oral cavity and pharynx.', false, 60),
  ('tuning', 'Tuning fork tests', 'SPECIALTY', 'Rinne and Weber.', false, 61),
  ('audiometry', 'Audiometry', 'SPECIALTY', 'Pure tone audiogram upload or entry.', false, 62),
  ('endoscopy', 'Endoscopy findings', 'SPECIALTY', 'Nasal or laryngeal endoscopy notes and images.', false, 63),
  ('lesion_map', 'Lesion body map', 'SPECIALTY', 'Mark lesions on a body outline and describe them.', false, 64),
  ('derm_photos', 'Clinical photos', 'SPECIALTY', 'Before and after photos, taken with photo consent.', false, 65),
  ('derm_proc', 'Procedure sessions', 'SPECIALTY', 'Peels, laser and other sessions with settings.', false, 66),
  ('glucose', 'Glucose & HbA1c log', 'SPECIALTY', 'Sugar readings and HbA1c with a trend chart.', false, 67),
  ('foot', 'Diabetic foot exam', 'SPECIALTY', 'Sensation, pulses and ulcers.', false, 68),
  ('insulin', 'Insulin regimen', 'SPECIALTY', 'Insulin type, units and timing.', false, 69),
  ('screening', 'Complication screening', 'SPECIALTY', 'Eye, kidney and nerve checks with due dates.', false, 70),
  ('ecg', 'ECG', 'SPECIALTY', 'ECG findings and upload.', false, 71),
  ('echo', 'Echo findings', 'SPECIALTY', 'EF, valves and wall motion.', false, 72),
  ('risk', 'Risk scores', 'SPECIALTY', 'Cardiovascular risk scores.', false, 73),
  ('lipids', 'Lipid trend', 'SPECIALTY', 'Lipid profile across visits.', false, 74),
  ('prakriti', 'Prakriti assessment', 'SPECIALTY', 'Vata, pitta and kapha constitution.', false, 75),
  ('nadi', 'Nadi pariksha', 'SPECIALTY', 'Pulse examination findings.', false, 76),
  ('ashtavidha', 'Ashtavidha pariksha', 'SPECIALTY', 'Eight-fold examination.', false, 77),
  ('panchakarma', 'Panchakarma plan', 'SPECIALTY', 'Procedures, days and diet plan.', false, 78),
  ('mse', 'Mental status examination', 'SPECIALTY', 'Appearance, mood, thought and cognition.', false, 79),
  ('scales', 'Rating scales', 'SPECIALTY', 'Standard questionnaires scored automatically.', false, 80),
  ('onc_stage', 'Cancer staging (TNM)', 'SPECIALTY', 'Site, TNM and stage group, with the date it was staged.', false, 81),
  ('onc_histo', 'Histopathology and markers', 'SPECIALTY', 'Biopsy report, grade, receptors and tumour markers with trend.', false, 82),
  ('onc_ecog', 'Performance status (ECOG)', 'SPECIALTY', 'ECOG 0–4 before every cycle; 3 or more usually means no chemo.', false, 83),
  ('onc_tox', 'Side effects (CTCAE grade)', 'SPECIALTY', 'Grade nausea, mucositis, neuropathy and others since the last cycle.', false, 84),
  ('onc_bsa', 'BSA and dose calculator', 'SPECIALTY', 'Height and weight give BSA; doses in mg/m² are calculated and checked.', false, 85),
  ('onc_labs', 'Pre-chemo blood check', 'SPECIALTY', 'ANC, platelets, Hb, creatinine and bilirubin against the regimen’s limits.', false, 86),
  ('onc_regimen', 'Chemo order and cycles', 'SPECIALTY', 'Regimen, dose level, double-check and send to day care; cycle course with payments.', false, 87),
  ('onc_board', 'Tumour board decision', 'SPECIALTY', 'Multidisciplinary plan: surgery, chemo, radiotherapy, palliative.', false, 88),
  ('onc_pain', 'Pain and palliative care', 'SPECIALTY', 'Pain score, WHO ladder step and symptom control.', false, 89),
  ('onc_scheme', 'Scheme / insurance (PM-JAY, MJPJAY)', 'COMPLIANCE', 'Package code, pre-approval and amount used per cycle.', false, 90),
  ('sx_findings', 'Surgical examination', 'SPECIALTY', 'Abdomen, hernia sites, per-rectal, local findings on the body map.', false, 91),
  ('sx_fitness', 'Fitness for surgery', 'SPECIALTY', 'ASA grade, other illnesses, blood thinners, PAC and pre-op tests.', false, 92),
  ('sx_plan', 'Surgery plan and OT booking', 'SPECIALTY', 'Procedure, approach, anaesthesia, admission type, OT date and slot, package estimate.', false, 93),
  ('sx_consent', 'Surgical consent', 'COMPLIANCE', 'Procedure, conversion, anaesthesia, blood and photo consent.', false, 94),
  ('sx_preop', 'Pre-op orders', 'SPECIALTY', 'Fasting, medicines to stop or continue, antibiotic, preparation.', false, 95),
  ('sx_checklist', 'WHO surgical safety checklist', 'COMPLIANCE', 'Sign in, time out and sign out in OT.', false, 96),
  ('sx_opnote', 'Operation notes', 'SPECIALTY', 'Findings, steps, implants, blood loss, specimen sent.', false, 97),
  ('sx_postop', 'Post-op orders and wound check', 'SPECIALTY', 'Drain, wound, stitch removal and day 7 / day 30 reviews.', false, 98),
  ('sx_preauth', 'Insurance pre-authorisation', 'COMPLIANCE', 'TPA, PM-JAY or MJPJAY pre-auth with estimate and reports.', false, 99),
  ('therapy_notes', 'Therapy notes (restricted)', 'SPECIALTY', 'Session notes visible only to the treating doctor.', false, 100);
